import type { Program, ProgramDay, ProgramWeek, Scheme, Slot } from '../types'

/**
 * The 12-week programs, built as typed content. Weeks are generated by small
 * builders so the structure stays readable; the emitted object is plain data
 * the engine consumes. Human-readable versions live in docs/programs/.
 */

/* ================= Golf Athlete 5/3/1 (intermediate) =================
 * Leader 1 (wks 1-3, 5s PRO + FSL) · deload wk 4 · Leader 2 (wks 5-7) ·
 * deload wk 8 · Anchor (wks 9-11, PR sets capped at RPE 9 + 3×5 FSL) ·
 * wk 12 TM test. Every session opens with mobility + jumps/throws.
 */

const RPE_CAP = 9

type WavePct = Array<{ pct: number; reps: number; amrap?: boolean }>

/** 5s PRO leader waves — straight fives, no grinding. */
const LEADER_WAVES: WavePct[] = [
  [{ pct: 0.65, reps: 5 }, { pct: 0.75, reps: 5 }, { pct: 0.85, reps: 5 }],
  [{ pct: 0.7, reps: 5 }, { pct: 0.8, reps: 5 }, { pct: 0.9, reps: 5 }],
  [{ pct: 0.75, reps: 5 }, { pct: 0.85, reps: 5 }, { pct: 0.95, reps: 5 }],
]

/** Anchor waves — classic 5/3/1 with a PR (AMRAP) top set. */
const ANCHOR_WAVES: WavePct[] = [
  [{ pct: 0.65, reps: 5 }, { pct: 0.75, reps: 5 }, { pct: 0.85, reps: 5, amrap: true }],
  [{ pct: 0.7, reps: 3 }, { pct: 0.8, reps: 3 }, { pct: 0.9, reps: 3, amrap: true }],
  [{ pct: 0.75, reps: 5 }, { pct: 0.85, reps: 3 }, { pct: 0.95, reps: 1, amrap: true }],
]

const DELOAD_WAVE: WavePct = [
  { pct: 0.4, reps: 5 },
  { pct: 0.5, reps: 5 },
  { pct: 0.6, reps: 5 },
]

function main531(liftKey: string, wave: WavePct, withCap = false): Scheme {
  return { kind: 'percentTM', liftKey, sets: wave, ...(withCap ? { rpeCap: RPE_CAP } : {}) }
}

/** First-Set-Last supplemental volume: sets×5 at the wave's first percentage. */
function fsl(liftKey: string, wave: WavePct, sets: number): Scheme {
  return {
    kind: 'percentTM',
    liftKey,
    sets: Array.from({ length: sets }, () => ({ pct: wave[0].pct, reps: 5 })),
  }
}

function fixed(sets: number, reps: number, extra?: Partial<Extract<Scheme, { kind: 'fixedSets' }>>): Scheme {
  return { kind: 'fixedSets', sets, reps, ...extra }
}

function dp(sets: number, repMin: number, repMax: number, startLbs: number, incrementLbs = 5): Scheme {
  return { kind: 'doubleProgression', sets, repMin, repMax, startLbs, incrementLbs }
}

const LOWER_PRIMER = ['90/90 hip switch × 8/side', 'Open book × 6/side', 'Leg swings × 10/side']
const UPPER_PRIMER = ['Open book × 6/side', 'Band pull-apart × 15', 'Shoulder CARs × 5/side']
const POWER_PRIMER = ["World's greatest stretch × 4/side", 'Hip airplane × 5/side', 'Deep squat hold 45s']

interface AthleteWeekOpts {
  wave: WavePct
  anchor: boolean
  deload: boolean
  /** anchor block alternates top-set emphasis between squat and trap-bar DL */
  dlEmphasis?: boolean
}

function athleteWeek(week: number, label: string, opts: AthleteWeekOpts): ProgramWeek {
  const { wave, anchor, deload, dlEmphasis } = opts
  const fslSets = deload ? 0 : anchor ? 3 : 5
  const acc = (slots: Slot[]): Slot[] => (deload ? slots.filter((s) => !s.id.endsWith('-acc')) : slots)

  const lowerMainLift = dlEmphasis ? 'deadlift' : 'squat'
  const lowerMainEx = dlEmphasis ? 'trap-bar-deadlift' : 'back-squat'
  const lowerFslLift = dlEmphasis ? 'squat' : 'deadlift'
  const lowerFslEx = dlEmphasis ? 'back-squat' : 'trap-bar-deadlift'

  const day1: ProgramDay = {
    day: 1,
    name: dlEmphasis ? 'Lower — Pull' : 'Lower — Squat',
    primer: LOWER_PRIMER,
    slots: acc([
      { id: 'd1-jump', exerciseId: 'trap-bar-jump', scheme: fixed(deload ? 3 : 5, 3, { note: 'Max intent. Full rest. Light load.' }), restSec: 90 },
      { id: 'd1-main', exerciseId: lowerMainEx, scheme: main531(lowerMainLift, wave, anchor), restSec: 300, heavyLower: true, golfAlternate: { exerciseId: 'banded-hinge', scheme: fixed(3, 8, { note: 'Fast hips, easy on recovery — round tomorrow.' }) } },
      ...(fslSets > 0
        ? [{ id: 'd1-fsl', exerciseId: lowerFslEx, scheme: fsl(lowerFslLift, wave, fslSets), restSec: 180, heavyLower: true, golfAlternate: { exerciseId: 'glute-bridge', scheme: fixed(3, 12) } } satisfies Slot]
        : []),
      { id: 'd1-split-acc', exerciseId: 'bulgarian-split-squat', scheme: dp(3, 8, 12, 40), restSec: 120 },
      { id: 'd1-ham-acc', exerciseId: 'nordic-curl', scheme: fixed(3, 4, { note: 'Assist with hands as needed. Slowest possible negative.' }), restSec: 120 },
      { id: 'd1-core-acc', exerciseId: 'half-kneeling-pallof', scheme: fixed(3, 10, { perSide: true }), restSec: 60 },
    ]),
  }

  const day2: ProgramDay = {
    day: 2,
    name: 'Upper — Bench',
    primer: UPPER_PRIMER,
    slots: acc([
      { id: 'd2-throw', exerciseId: 'mb-chest-pass', scheme: fixed(deload ? 2 : 3, 5, { note: 'Throw hard. This is speed work, not cardio.' }), restSec: 90 },
      { id: 'd2-main', exerciseId: 'bench-press', scheme: main531('bench', wave, anchor), restSec: 300 },
      ...(fslSets > 0 ? [{ id: 'd2-fsl', exerciseId: 'bench-press', scheme: fsl('bench', wave, fslSets), restSec: 180 } satisfies Slot] : []),
      { id: 'd2-chin-acc', exerciseId: 'chin-up', scheme: dp(3, 6, 10, 0, 5), supersetGroup: 'A', restSec: 120 },
      { id: 'd2-row-acc', exerciseId: 'one-arm-db-row', scheme: dp(3, 8, 12, 60), supersetGroup: 'A', restSec: 120 },
      { id: 'd2-face-acc', exerciseId: 'band-face-pull', scheme: fixed(3, 15), restSec: 60 },
      { id: 'd2-carry-acc', exerciseId: 'suitcase-carry', scheme: fixed(3, 1, { perSide: true, note: '40 m per side, heavy. Stand tall.' }), restSec: 90 },
    ]),
  }

  const day3: ProgramDay = {
    day: 3,
    name: 'Golf Power',
    primer: POWER_PRIMER,
    slots: [
      { id: 'd3-scoop', exerciseId: 'mb-rotational-scoop-toss', scheme: fixed(deload ? 2 : 4, 3, { perSide: true, note: 'Full speed. Stop the set if speed drops.' }), restSec: 120 },
      { id: 'd3-step', exerciseId: 'mb-step-behind-throw', scheme: fixed(deload ? 2 : 3, 3, { perSide: true }), restSec: 120 },
      { id: 'd3-broad', exerciseId: 'broad-jump', scheme: fixed(3, 3, { note: 'Stick every landing.' }), restSec: 120 },
      { id: 'd3-bound', exerciseId: 'lateral-bound', scheme: fixed(3, 3, { perSide: true }), restSec: 90 },
      { id: 'd3-chop', exerciseId: 'band-chop', scheme: fixed(3, 8, { perSide: true }), restSec: 60 },
      { id: 'd3-z2', exerciseId: 'treadmill-zone2', scheme: { kind: 'timeDistance', minutes: 25, zone: 'z2', note: 'Optional finisher — skip if short on time.' }, restSec: 0 },
    ],
  }

  const day4: ProgramDay = {
    day: 4,
    name: 'Press + Arms',
    primer: UPPER_PRIMER,
    slots: acc([
      { id: 'd4-slam', exerciseId: 'mb-overhead-slam', scheme: fixed(deload ? 2 : 3, 5, { note: 'Full-body snap. Throw through the floor.' }), restSec: 90 },
      { id: 'd4-main', exerciseId: 'overhead-press', scheme: main531('press', wave, anchor), restSec: 300 },
      ...(fslSets > 0 ? [{ id: 'd4-fsl', exerciseId: 'overhead-press', scheme: fsl('press', wave, fslSets), restSec: 180 } satisfies Slot] : []),
      { id: 'd4-dip-acc', exerciseId: 'dips', scheme: dp(3, 8, 12, 0, 5), supersetGroup: 'A', restSec: 120 },
      { id: 'd4-pull-acc', exerciseId: 'pull-up', scheme: dp(3, 6, 10, 0, 5), supersetGroup: 'A', restSec: 120 },
      { id: 'd4-curl-acc', exerciseId: 'barbell-curl', scheme: dp(3, 8, 12, 45), restSec: 90 },
      { id: 'd4-cuff-acc', exerciseId: 'band-external-rotation', scheme: fixed(2, 12, { perSide: true }), restSec: 45 },
    ]),
  }

  return { week, label, deload: deload || undefined, days: [day1, day2, day3, day4] }
}

function tmTestWeek(week: number): ProgramWeek {
  const testDay = (day: number, name: string, liftKey: string, exerciseId: string, extras: Slot[]): ProgramDay => ({
    day,
    name,
    primer: day === 1 ? LOWER_PRIMER : UPPER_PRIMER,
    slots: [
      { id: `d${day}-test`, exerciseId, scheme: { kind: 'tmTest', liftKey }, restSec: 300 },
      ...extras,
    ],
  })
  return {
    week,
    label: 'Test week — prove the block',
    days: [
      testDay(1, 'Test — Squat + Pull', 'squat', 'back-squat', [
        { id: 'd1-test2', exerciseId: 'trap-bar-deadlift', scheme: { kind: 'tmTest', liftKey: 'deadlift' }, restSec: 300 },
      ]),
      testDay(2, 'Test — Bench', 'bench', 'bench-press', [
        { id: 'd2-chin', exerciseId: 'chin-up', scheme: fixed(3, 5), restSec: 120 },
      ]),
      {
        day: 3,
        name: 'Golf Power — light',
        primer: POWER_PRIMER,
        slots: [
          { id: 'd3-scoop', exerciseId: 'mb-rotational-scoop-toss', scheme: fixed(3, 3, { perSide: true }), restSec: 120 },
          { id: 'd3-broad', exerciseId: 'broad-jump', scheme: fixed(2, 3), restSec: 120 },
          { id: 'd3-z2', exerciseId: 'treadmill-zone2', scheme: { kind: 'timeDistance', minutes: 30, zone: 'z2' }, restSec: 0 },
        ],
      },
      testDay(4, 'Test — Press', 'press', 'overhead-press', [
        { id: 'd4-dip', exerciseId: 'dips', scheme: fixed(3, 8), restSec: 120 },
      ]),
    ],
  }
}

