/* ================= Foundations (novice, 3 days) =================
 * Weeks 1-2: technique — groove the barbell patterns light.
 * Weeks 3-12: GZCLP rotation (A1 B1 A2 / B2 A1 B1 / ...), T3 double
 * progression, golf touch on day 3, encouragement built into the copy.
 */

const FOUNDATION_PRIMER = ['Cat-cow × 8', '90/90 hip switch × 6/side', 'Band lateral walk × 10/side']

const T1_STAGES = [
  { sets: 5, reps: 3, amrapLast: true },
  { sets: 6, reps: 2, amrapLast: true },
  { sets: 10, reps: 1, amrapLast: true },
]
const T2_STAGES = [
  { sets: 3, reps: 10, amrapLast: false },
  { sets: 3, reps: 8, amrapLast: false },
  { sets: 3, reps: 6, amrapLast: false },
]

function t1(liftKey: string): Scheme {
  return { kind: 'linearStages', liftKey, stages: T1_STAGES, incrementLbs: liftKey === 'bench' || liftKey === 'press' ? 5 : 10 }
}
function t2(liftKey: string): Scheme {
  return { kind: 'linearStages', liftKey: liftKey + '-t2', stages: T2_STAGES, incrementLbs: 5 }
}

interface GzclpTemplate {
  name: string
  t1Lift: string
  t1Ex: string
  t2Lift: string
  t2Ex: string
  t3: Slot[]
}

const GZCLP_DAYS: GzclpTemplate[] = [
  {
    name: 'A1 — Squat focus',
    t1Lift: 'squat', t1Ex: 'back-squat',
    t2Lift: 'bench', t2Ex: 'bench-press',
    t3: [
      { id: 't3-row', exerciseId: 'one-arm-db-row', scheme: dp(3, 10, 15, 20), restSec: 90 },
      { id: 't3-core', exerciseId: 'dead-bug', scheme: fixed(3, 8, { perSide: true }), restSec: 60 },
    ],
  },
  {
    name: 'B1 — Press focus',
    t1Lift: 'press', t1Ex: 'overhead-press',
    t2Lift: 'deadlift', t2Ex: 'trap-bar-deadlift',
    t3: [
      { id: 't3-hip', exerciseId: 'db-hip-thrust', scheme: dp(3, 10, 15, 25), restSec: 90 },
      { id: 't3-side', exerciseId: 'side-plank', scheme: fixed(3, 1, { perSide: true, note: 'Hold 20-40s per side. Quality over clock.' }), restSec: 60 },
    ],
  },
  {
    name: 'A2 — Bench focus',
    t1Lift: 'bench', t1Ex: 'bench-press',
    t2Lift: 'squat', t2Ex: 'back-squat',
    t3: [
      { id: 't3-chin', exerciseId: 'band-assisted-chin-up', scheme: dp(3, 5, 8, 0, 0), restSec: 90 },
      { id: 't3-pallof', exerciseId: 'pallof-press', scheme: fixed(3, 10, { perSide: true }), restSec: 60 },
    ],
  },
  {
    name: 'B2 — Deadlift focus',
    t1Lift: 'deadlift', t1Ex: 'trap-bar-deadlift',
    t2Lift: 'press', t2Ex: 'overhead-press',
    t3: [
      { id: 't3-scoop', exerciseId: 'mb-rotational-scoop-toss', scheme: fixed(3, 3, { perSide: true, note: 'Throw it like you mean it — this is your golf speed.' }), restSec: 90 },
      { id: 't3-pull', exerciseId: 'band-pull-apart', scheme: fixed(3, 15), restSec: 60 },
    ],
  },
]

function gzclpDay(dayNum: number, template: GzclpTemplate): ProgramDay {
  return {
    day: dayNum,
    name: template.name,
    primer: FOUNDATION_PRIMER,
    slots: [
      { id: `t1-${template.t1Lift}`, exerciseId: template.t1Ex, scheme: t1(template.t1Lift), restSec: 180, heavyLower: template.t1Lift === 'squat' || template.t1Lift === 'deadlift', golfAlternate: { exerciseId: 'glute-bridge', scheme: fixed(3, 12, { note: 'Light day — round tomorrow.' }) } },
      { id: `t2-${template.t2Lift}`, exerciseId: template.t2Ex, scheme: t2(template.t2Lift), restSec: 120 },
      ...template.t3,
    ],
  }
}

function techniqueWeek(week: number): ProgramWeek {
  const day = (dayNum: number, name: string, slots: Slot[]): ProgramDay => ({
    day: dayNum,
    name,
    primer: FOUNDATION_PRIMER,
    slots,
  })
  const note = 'Empty bar or light. You are grooving the pattern, not chasing weight — that comes soon.'
  return {
    week,
    label: 'Technique — light on purpose, momentum stays',
    days: [
      day(1, 'Full Body A + squat practice', [
        { id: 'tech-squat', exerciseId: 'back-squat', scheme: fixed(3, 5, { loadLbs: 45, note }), restSec: 120 },
        { id: 'gob', exerciseId: 'goblet-squat', scheme: dp(3, 8, 12, 25), restSec: 90 },
        { id: 'dbb', exerciseId: 'db-bench-press', scheme: dp(3, 8, 12, 30), restSec: 90 },
        { id: 'row', exerciseId: 'one-arm-db-row', scheme: dp(3, 10, 12, 20), restSec: 90 },
        { id: 'plank', exerciseId: 'plank', scheme: fixed(3, 1, { note: 'Hold 25-45s. Straight line, strong breath.' }), restSec: 60 },
      ]),
      day(2, 'Full Body B + press practice', [
        { id: 'tech-press', exerciseId: 'overhead-press', scheme: fixed(3, 5, { loadLbs: 45, note }), restSec: 120 },
        { id: 'lunge', exerciseId: 'db-reverse-lunge', scheme: dp(3, 8, 10, 15), restSec: 90 },
        { id: 'rdl', exerciseId: 'db-rdl', scheme: dp(3, 10, 12, 40), restSec: 90 },
        { id: 'csrow', exerciseId: 'chest-supported-db-row', scheme: dp(3, 10, 12, 20), restSec: 90 },
        { id: 'bug', exerciseId: 'dead-bug', scheme: fixed(3, 8, { perSide: true }), restSec: 60 },
      ]),
      day(3, 'Full Body C + hinge practice', [
        { id: 'tech-dl', exerciseId: 'trap-bar-deadlift', scheme: fixed(3, 5, { loadLbs: 65, note }), restSec: 120 },
        { id: 'hip', exerciseId: 'db-hip-thrust', scheme: dp(3, 10, 15, 25), restSec: 90 },
        { id: 'incl', exerciseId: 'incline-db-press', scheme: dp(3, 8, 12, 25), restSec: 90 },
        { id: 'scoop', exerciseId: 'mb-rotational-scoop-toss', scheme: fixed(3, 3, { perSide: true, note: 'Light ball, big speed. Golf power starts here.' }), restSec: 90 },
        { id: 'side', exerciseId: 'side-plank', scheme: fixed(2, 1, { perSide: true, note: 'Hold 15-30s per side.' }), restSec: 60 },
      ]),
    ],
  }
}

function gzclpWeek(week: number): ProgramWeek {
  // Rotation continues across weeks: wk3 = A1 B1 A2, wk4 = B2 A1 B1, ...
  const startIndex = (week - 3) * 3
  const days: ProgramDay[] = [0, 1, 2].map((i) => gzclpDay(i + 1, GZCLP_DAYS[(startIndex + i) % 4]))
  return { week, label: `GZCLP · ${days.map((d) => d.name.split(' ')[0]).join(' ')}`, days }
}

export const foundations: Program = {
  id: 'foundations-gzclp',
  name: 'Foundations',
  tagline: '12 weeks · 3 days · from new-to-barbells to genuinely strong',
  description:
    'Two weeks of light technique work to groove the barbell patterns, then ten weeks of GZCLP — the best-regarded beginner progression there is. Every session has one heavy focus lift, one supporting lift, and accessory work you can push. When a weight stalls, the program changes the rep scheme instead of punishing you — stalls are planned, not failures. Milestones get named along the way: first bodyweight squat, first full push-up, first chin-up.',
  level: 'beginner',
  daysPerWeek: 3,
  lifts: [
    { key: 'squat', exerciseId: 'back-squat', tmIncrementLbs: 0 },
    { key: 'bench', exerciseId: 'bench-press', tmIncrementLbs: 0 },
    { key: 'deadlift', exerciseId: 'trap-bar-deadlift', tmIncrementLbs: 0 },
    { key: 'press', exerciseId: 'overhead-press', tmIncrementLbs: 0 },
  ],
  weeks: [
    techniqueWeek(1),
    techniqueWeek(2),
    ...Array.from({ length: 10 }, (_, i) => gzclpWeek(i + 3)),
  ],
}

export const programs: Program[] = [golfAthlete531, foundations]

export function getProgram(id: string): Program | undefined {
  return programs.find((p) => p.id === id)
}

/** Default starting loads for Foundations linearStages, by liftKey (incl. -t2 keys). */
export const FOUNDATION_DEFAULT_LOADS: Record<string, number> = {
  squat: 45, 'squat-t2': 45,
  bench: 45, 'bench-t2': 45,
  deadlift: 75, 'deadlift-t2': 65,
  press: 45, 'press-t2': 45,
}
